import React from 'react';
import { FormItem, FormButtonGroup, Submit, Cascader } from '@storage-fe/formily-arco';
import { createForm, onFieldReact, FormPathPattern, Field } from '@formily/core';
import { FormProvider, createSchemaField } from '@formily/react';
import { action } from '@formily/reactive';

const SchemaField = createSchemaField({
  components: {
    Cascader,
    FormItem,
  },
});

const handleAddress = (pattern: FormPathPattern) => {
  const transform = (data = {}) =>
    Object.entries(data).reduce((buf: any[], [key, value]: any) => {
      if (typeof value === 'string') {
        return buf.concat({
          label: value,
          value: key,
        });
      }
      const { name, code, cities, districts } = value;
      const _cities: any = transform(cities);
      const _districts: any = transform(districts);
      return buf.concat({
        label: name,
        value: code,
        children: _cities.length ? _cities : _districts.length ? _districts : undefined,
      });
    }, []);
  onFieldReact(pattern, (field: Field) => {
    field.loading = true;
    fetch('//unpkg.com/china-location/dist/location.json')
      .then(res => res.json())
      .then(
        action.bound?.(data => {
          field.dataSource = transform(data);
          field.loading = false;
        })
      );
  });
};

const form = createForm({
  effects: () => {
    handleAddress('address');
  },
});

export default () => (
  <FormProvider form={form}>
    <SchemaField>
      <SchemaField.String
        name="address"
        title="地址选择"
        required
        x-decorator="FormItem"
        x-component="Cascader"
        x-component-props={{
          style: {
            width: 240,
          },
        }}
      />
    </SchemaField>
    <FormButtonGroup>
      <Submit onSubmit={console.log}>提交</Submit>
    </FormButtonGroup>
  </FormProvider>
);
